// Convierte un número a su representación en letras (pesos colombianos), para el "SON:" del comprobante.
const UNIDADES = ["", "UNO", "DOS", "TRES", "CUATRO", "CINCO", "SEIS", "SIETE", "OCHO", "NUEVE"];
const DECENAS = ["DIEZ", "ONCE", "DOCE", "TRECE", "CATORCE", "QUINCE", "DIECISÉIS", "DIECISIETE", "DIECIOCHO", "DIECINUEVE", "VEINTE"];
const DECENAS_DECIMAL = ["", "", "VEINTI", "TREINTA", "CUARENTA", "CINCUENTA", "SESENTA", "SETENTA", "OCHENTA", "NOVENTA"];
const CENTENAS = ["", "CIENTO", "DOSCIENTOS", "TRESCIENTOS", "CUATROCIENTOS", "QUINIENTOS", "SEISCIENTOS", "SETECIENTOS", "OCHOCIENTOS", "NOVECIENTOS"];
const CAUSAS_LIQUIDACION = ["Retiro voluntario", "Terminación con justa causa", "Terminación sin justa causa", "Mutuo acuerdo", "Terminación de contrato a término fijo", "Pensión / jubilación"];
function numeroATexto(n) {
  n = Math.round(Math.abs(n || 0));
  if (n === 0) return "CERO";
  function trescientos(num) {
    if (num === 0) return "";
    if (num === 100) return "CIEN";
    let texto = "";
    const c = Math.floor(num / 100), d = Math.floor((num % 100) / 10), u = num % 10;
    if (c > 0) texto += CENTENAS[c] + " ";
    const resto = num % 100;
    if (resto <= 9) texto += UNIDADES[resto];
    else if (resto <= 20) texto += DECENAS[resto - 10];
    else if (d === 2) texto += (DECENAS_DECIMAL[2] + (u > 0 ? UNIDADES[u].toLowerCase() === "uno" ? "ÚN" : UNIDADES[u] : "")).trim();
    else texto += DECENAS_DECIMAL[d] + (u > 0 ? " Y " + UNIDADES[u] : "");
    return texto.trim();
  }
  function seccion(num, singular, plural) {
    if (num === 0) return "";
    if (num === 1) return singular ? "UN " + singular : "UN";
    const texto = num < 1000 ? trescientos(num) : seccion(Math.floor(num / 1000), "", "") + " MIL" + (num % 1000 > 0 ? " " + trescientos(num % 1000) : "");
    return texto.trim() + (plural ? " " + plural : "");
  }
  const millones = Math.floor(n / 1000000);
  const miles = Math.floor((n % 1000000) / 1000);
  const resto = n % 1000;
  let partes = [];
  if (millones > 0) partes.push(millones === 1 ? "UN MILLÓN" : trescientos(millones) + " MILLONES");
  if (miles > 0) partes.push((miles === 1 ? "MIL" : trescientos(miles) + " MIL"));
  if (resto > 0 || partes.length === 0) partes.push(trescientos(resto));
  return partes.join(" ").replace(/\s+/g, " ").trim();
}
function valorEnLetras(n) {
  return `${numeroATexto(n)} PESOS M/CTE`;
}

