// Liquidación real de prestaciones sociales, año comercial de 360 días
// (12 meses de 30) — mismo criterio confirmado para toda la nómina.
function esFinDeMes(fechaObj) {
  const siguiente = new Date(fechaObj);
  siguiente.setDate(siguiente.getDate() + 1);
  return siguiente.getMonth() !== fechaObj.getMonth();
}
// Solo para PRESENTACIÓN (contabilidad, comprobantes, Excel) — el período se
// muestra cerrado con el día anterior a la fecha de corte (ej. "01/03/2023 al
// 29/02/2024" en vez de "01/03/2023 al 01/03/2024"), aunque el cálculo interno
// de días (que sí exige contar de fecha a fecha, Art. 59 Ley 4/1913) sigue
// usando la fecha de corte real, sin este ajuste — así los 15 días de
// vacaciones no cambian, solo cómo se lee la fecha de cierre.
function diaAnterior(fechaISO) {
  if (!fechaISO) return fechaISO;
  const d = new Date(fechaISO + "T00:00:00");
  d.setDate(d.getDate() - 1);
  return d.toISOString().slice(0, 10);
}
// Inversa de diaAnterior: convierte una fecha escrita en convención "día
// anterior" (ej. 28 de febrero, como cierre de un año que empezó 1 de
// marzo) a la fecha de corte real que exige el cálculo (1 de marzo) — así
// el campo de "último período pagado" se puede llenar con la convención
// contable de la empresa sin que eso cambie el resultado de 15 días.
function diaSiguiente(fechaISO) {
  if (!fechaISO) return fechaISO;
  const d = new Date(fechaISO + "T00:00:00");
  d.setDate(d.getDate() + 1);
  return d.toISOString().slice(0, 10);
}
function diasComercialesEntre(fechaInicio, fechaFin) {
  const i = new Date(fechaInicio + "T00:00:00");
  const f = new Date(fechaFin + "T00:00:00");
  if (f <= i) return 0;
  // Convención 30/360 ("Bond Basis"), el año comercial de 360 días que usa
  // la normatividad laboral colombiana: cada mes cuenta como 30 días
  // exactos. La regla correcta no es "si el día es 31", sino "si la fecha
  // es el último día REAL de su mes" — así también cubre febrero (28 o 29
  // días reales cuentan igual como 30 comerciales), no solo los meses de 31.
  let d1 = esFinDeMes(i) ? 30 : i.getDate();
  let d2 = esFinDeMes(f) ? 30 : f.getDate();
  const dias = (f.getFullYear() - i.getFullYear()) * 360 + (f.getMonth() - i.getMonth()) * 30 + (d2 - d1);
  // Diferencia simple (SIN +1): correcta para "misma fecha, N períodos
  // después" (ej. 2025-03-01 a 2026-03-01 = 360 exactos, no 361) — el caso
  // de vacaciones, que encadena la fecha de corte anterior con la nueva.
  // Para rangos "primer día a último día del período" (cesantías/prima,
  // donde ambos extremos son días de servicio inclusive, ej. 1-ene a
  // 31-dic), se le suma 1 explícitamente en el punto donde se usa así,
  // no aquí — porque esa es una semántica distinta a la de vacaciones.
  return Math.max(0, dias);
}
// Días hábiles de DISFRUTE de vacaciones: solo domingo y festivos no cuentan
// (el sábado sí es hábil para este efecto, a diferencia de otros cálculos
// laborales). Ambas fechas inclusive.
function esDiaHabilVacaciones(fecha) {
  return fecha.getDay() !== 0 && !FESTIVOS_2026.includes(fecha.toISOString().slice(0, 10));
}
function diasHabilesDisfrute(fechaSalida, fechaUltimoDia) {
  if (!fechaSalida || !fechaUltimoDia) return 0;
  let f = new Date(fechaSalida + "T00:00:00");
  const fin = new Date(fechaUltimoDia + "T00:00:00");
  if (fin < f) return 0;
  let count = 0;
  while (f <= fin) {
    if (esDiaHabilVacaciones(f)) count++;
    f.setDate(f.getDate() + 1);
  }
  return count;
}
function diasCalendarioEntre(fechaInicio, fechaFin) {
  if (!fechaInicio || !fechaFin) return 0;
  const i = new Date(fechaInicio + "T00:00:00");
  const f = new Date(fechaFin + "T00:00:00");
  return Math.round((f - i) / 86400000) + 1;
}
function calcularCesantias(salarioPromedio, diasTrabajados) {
  return Math.round((salarioPromedio * diasTrabajados) / 360);
}
function calcularInteresesCesantias(cesantias) {
  // 12% anual sobre el valor de cesantías que se va a consignar al fondo —
  // no se vuelve a multiplicar por días: esa proporción ya quedó reflejada
  // en el propio valor de las cesantías (que ya descontó lo que corresponda
  // por ausencia injustificada, vía el dinero, no los días).
  return Math.round(cesantias * 0.12);
}
function calcularPrima(salarioPromedio, diasTrabajados) {
  return Math.round((salarioPromedio * diasTrabajados) / 360);
}
function calcularVacaciones(salarioBasico, diasTrabajados) {
  const diasCausados = (15 * diasTrabajados) / 360;
  const valor = Math.round((salarioBasico * diasTrabajados) / 720);
  return { diasCausados: Math.round(diasCausados * 100) / 100, valor };
}
const CATEGORIAS_COSTO = ["MATERIALES", "MANO_OBRA", "SUBCONTRATO", "EQUIPOS", "SERVICIOS_PUBLICOS", "OTROS"];

// Divisor mensual vigente desde el 15 de julio de 2026 (jornada de 42h, Ley 2101 de 2021).
// Antes de esa fecha era 220. Confirma con tu contador si liquidas un período que cruza el cambio.
const MESES = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];
function periodoQuincenalLabel(mesNomina, quincena) {
  if (!mesNomina || !quincena) return null;
  const [anio, mes] = mesNomina.split("-").map(Number);
  const nombreMes = MESES[mes - 1];
  const ultimoDia = new Date(anio, mes, 0).getDate();
  return quincena === "1" ? `${nombreMes} ${anio} - 1ª quincena (1-15)` : `${nombreMes} ${anio} - 2ª quincena (16-${ultimoDia})`;
}

// Fecha real (no solo la etiqueta) del último día de la quincena elegida —
// se usa como "fecha" del registro de nómina en vez del campo genérico de
// fecha del formulario, para que SIEMPRE caiga dentro del período de pago
// seleccionado. Si dependiera del campo "Fecha" suelto, un descuido ahí
// desalinearía la fecha real del registro respecto al período que se
// escogió, y la nómina histórica que usan cesantías y prima buscaría en el
// rango equivocado.
function fechaFinQuincena(mesNomina, quincena) {
  if (!mesNomina || !quincena) return null;
  const [anio, mes] = mesNomina.split("-").map(Number);
  if (quincena === "1") return `${mesNomina}-15`;
  const ultimoDia = new Date(anio, mes, 0).getDate();
  return `${mesNomina}-${String(ultimoDia).padStart(2, "0")}`;
}

// La 1ª quincena siempre son 15 días (1-15). La 2ª va del 16 al último día
// del mes, así que varía: 13 en febrero no bisiesto, 14 en bisiesto, 15 en
// meses de 30, 16 en meses de 31 — nunca es fija en 15.
function diasEnQuincena(mesNomina, quincena) {
  // El mes comercial siempre tiene 30 días para efectos de liquidación
  // (normatividad laboral colombiana), así que cada quincena son 15 días
  // fijos — sin importar si el mes calendario tiene 28, 29, 30 o 31.
  return 15;
}

