          {infoProveedor?.direccion && <p><span className="text-slate-500">Dirección:</span> {infoProveedor.direccion}</p>}
          {infoProveedor?.telefono && <p><span className="text-slate-500">Teléfono:</span> {infoProveedor.telefono}</p>}
