                          <option key={o.id} value={o.id}>{o.fecha} · {o.tipo === "NOMINA" ? "Nómina" : o.concepto} — {fmt(o.valor)}{etiquetaAsignacion(o) ? ` (${etiquetaAsignacion(o)})` : ""}</option>
